package cn.servicehub.workflow.team;import java.util.Map;import java.util.Optional;import java.util.concurrent.ConcurrentHashMap;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Repository;@Repository@Profile("!mysql")public class InMemorySupportQueueReconciliationRepository implements SupportQueueReconciliationRepository{private final Map<String,SupportQueueReconciliationRequest>m=new ConcurrentHashMap<>();public void create(SupportQueueReconciliationRequest r){if(m.putIfAbsent(r.id(),r)!=null)throw new cn.servicehub.workflow.application.WorkflowConflictException();}public Optional<SupportQueueReconciliationRequest>find(String id){return Optional.ofNullable(m.get(id));}public synchronized boolean approve(SupportQueueReconciliationRequest r,long v){SupportQueueReconciliationRequest o=m.get(r.id());if(o==null||o.version()!=v||!"PENDING".equals(o.status()))return false;m.put(r.id(),r);return true;}}
